def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    try:
        from datetime import datetime, timezone, time

        if tz is None:
            # Assuming LocalTime if no timezone is provided
            dt = datetime.fromtimestamp(nanoseconds / 1e9)
            return dt.time()
        else:
            # Assuming Time with timezone if timezone is provided
            dt = datetime.fromtimestamp(nanoseconds / 1e9, tz=timezone(tz))
            return dt.time()
    except Exception as e:
        raise ValueError(f"Error hydrating time: {e}")

def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if not isinstance(value, timedelta):
        raise ValueError("Value must be an instance of timedelta")
    return {
        'days': value.days,
        'seconds': value.seconds,
        'microseconds': value.microseconds
    }

