def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    try:
        if not isinstance(name, str) or not name:
            raise ValueError("Name must be a non-empty string.")

        if not isinstance(fields, dict):
            raise ValueError("Fields must be a dictionary.")

        if not isinstance(srid_map, dict):
            raise ValueError("SRID map must be a dictionary.")

        class Point:
            def __init__(self, **kwargs):
                for field in fields:
                    if field in kwargs:
                        setattr(self, field, kwargs[field])
                    else:
                        raise TypeError(f"Missing required field: {field}")
                if 'srid' in kwargs:
                    srid = kwargs['srid']
                    if srid not in srid_map:
                        raise ValueError(f"Invalid SRID: {srid}. Must be one of {list(srid_map.keys())}")
                    self.srid = srid
                else:
                    raise TypeError("Missing required field: srid")

        Point.__name__ = name
        return Point

    except Exception as e:
        print(f"Error creating Point subclass: {e}")
        return None

