def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            try:
                cache_key = key(*args, **kwargs)
                with lock if lock else nullcontext():
                    if cache_key in cache:
                        return cache[cache_key]
                    result = func(*args, **kwargs)
                    cache[cache_key] = result
                    return result
            except Exception as e:
                raise RuntimeError(f"An error occurred while caching: {e}")
        return wrapper
    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    if maxsize is not None and not isinstance(maxsize, int):
        raise TypeError(f'Expected maxsize to be an integer or None, got {type(maxsize).__name__}')
    if maxsize is not None and maxsize < 0:
        raise ValueError(f'Expected maxsize to be a non-negative integer or None, got {maxsize}')

    def decorator(func):
        from collections import OrderedDict

        cache = OrderedDict()
        cache_get = cache.get
        cache_move_to_end = cache.move_to_end
        cache_popitem = cache.popitem

        def wrapper(*args, **kwargs):
            if typed:
                key = (args, tuple(sorted(kwargs.items())))
            else:
                key = (args, frozenset(kwargs.items()))

            if maxsize is None:
                result = func(*args, **kwargs)
            elif (hit := cache_get(key, _missing)) is not _missing:
                cache_move_to_end(key)
            else:
                result = func(*args, **kwargs)
                cache[key] = result
                if len(cache) > maxsize:
                    cache_popitem(last=False)

            return result

        def cache_clear():
            nonlocal cache
            cache = OrderedDict()

        def cache_stats():
            return (len(cache), maxsize)

        wrapper.cache_clear = cache_clear
        wrapper.cache_stats = cache_stats

        return wrapper

    return decorator

def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        from collections import defaultdict
        from functools import wraps

        cache = {}
        frequency = defaultdict(int)
        if maxsize <= 0:
            maxsize = None

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = args if not typed else (args, tuple(sorted(kwargs.items())))
            try:
                result = cache[key]
                frequency[key] += 1
                return result
            except KeyError:
                if maxsize is not None and len(cache) >= maxsize:
                    # Find the least frequently used item
                    lfu_key = min(cache, key=lambda k: frequency[k])
                    del cache[lfu_key]
                    del frequency[lfu_key]
                result = func(*args, **kwargs)
                cache[key] = result
                frequency[key] = 1
                return result

        return wrapper

    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        if not self:
            raise KeyError("popitem(): dictionary is empty")
        first_key = next(iter(self))
        return first_key, self.pop(first_key)
    except Exception as e:
        raise KeyError(f"An error occurred: {e}")

