def cachedmethod(cache, key=hashkey, lock=None):
    def decorator(method):
        def wrapper(*args, **kwargs):
            k = key(*args, **kwargs)
            try:
                with lock:
                    if k in cache:
                        return cache[k]
            except TypeError:
                # Cache or lock is not thread-safe or not provided
                if k in cache:
                    return cache[k]
            result = method(*args, **kwargs)
            try:
                with lock:
                    cache[k] = result
            except TypeError:
                # Cache or lock is not thread-safe or not provided
                cache[k] = result
            return result
        return wrapper
    return decorator

