def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    try:
        self.context = {}
        if hasattr(self, 'initial_value'):
            self.bins = {key: self.initial_value for key in self.bins}
        elif hasattr(self, 'make_bins'):
            self.bins = self.make_bins()
        else:
            raise AttributeError("Neither initial_value nor make_bins is defined")
    except Exception as e:
        raise RuntimeError(f"Error resetting histogram: {e}")

