def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise ValueError("Both d1 and d2 must be dictionaries.")
    if level == 0:
        return {}
    diff = {}
    for key, value in d1.items():
        if key not in d2:
            diff[key] = value
        elif isinstance(value, dict) and isinstance(d2[key], dict):
            sub_diff = difference(value, d2[key], level - 1 if level > 0 else -1)
            if sub_diff:
                diff[key] = sub_diff
        elif value != d2[key]:
            diff[key] = value
    return diff

def fill(self, coord, weight=1):
    try:
        if not isinstance(coord, tuple):
            raise ValueError("coord must be a tuple")
        if not all(isinstance(c, int) and 0 <= c < dim for c, dim in zip(coord, self.shape)):
            return  # Coordinates outside the histogram edges are ignored
        if not isinstance(weight, (int, float)):
            raise ValueError("weight must be a number")
        self.data[coord] += weight
    except Exception as e:
        print(f"An error occurred: {e}")

def _validate_labels(labels):
    import re
    from collections.abc import Mapping

    key_regex = re.compile(r'^[a-zA-Z0-9_]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9_ -]+$')
    errors = []

    if not isinstance(labels, Mapping):
        raise ValidationError([{'labels': 'expected a dictionary'}])

    for key, value in labels.items():
        key_str = str(key)
        value_str = str(value)

        if not isinstance(key, (str, int, float, bool)):
            errors.append({key_str: 'expected string or bytes-like object'})
            continue

        if not isinstance(value, (str, int, float, bool)):
            errors.append({value_str: 'expected string or bytes-like object'})
            continue

        if not key_regex.match(key_str):
            errors.append({key_str: f"Label key '{key_str}' does not match the regex '^[a-zA-Z0-9_]+$'"})

        if not value_regex.match(value_str):
            errors.append({value_str: f"Label value '{value_str}' does not match the regex '^[a-zA-Z0-9_ -]+$'"})

    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    if not isinstance(manifest_dict, dict):
        raise ValueError("manifest_dict must be a dictionary")

    observer_schema = {}
    identifying_fields = {"apiVersion", "kind", "metadata", "name"}

    for key, value in manifest_dict.items():
        if first_level and key in identifying_fields:
            observer_schema[key] = value
        elif isinstance(value, dict):
            observer_schema[key] = generate_default_observer_schema_dict(value)
        elif isinstance(value, list):
            observer_schema[key] = [generate_default_observer_schema_dict(item) if isinstance(item, dict) else None for item in value]
        else:
            observer_schema[key] = None

    return observer_schema

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    try:
        if not isinstance(last_applied_manifest, list) or not isinstance(observer_schema, list) or not isinstance(response, list):
            raise ValueError("All arguments must be lists.")

        for schema_item, resp_item in zip(observer_schema, response):
            if isinstance(schema_item, dict) and isinstance(resp_item, dict):
                # Assuming there's a corresponding function to handle dictionary updates
                update_last_applied_manifest_dict_from_resp(last_applied_manifest, schema_item, resp_item)
            elif isinstance(schema_item, list) and isinstance(resp_item, list):
                update_last_applied_manifest_list_from_resp(last_applied_manifest, schema_item, resp_item)
            else:
                for i, schema_field in enumerate(schema_item):
                    if len(last_applied_manifest) <= i:
                        last_applied_manifest.append(None)
                    if last_applied_manifest[i] is None:
                        last_applied_manifest[i] = resp_item[i] if len(resp_item) > i else None
    except Exception as e:
        print(f"An error occurred: {e}")

def generate_default_observer_schema(app):
    try:
        observer_schema = {}
        for resource in app.spec.manifest:
            if resource not in app.spec.observer_schema:
                default_schema = {
                    "jobs": {
                        "success": ["Status.conditions[?type=='Complete'].status"],
                        "failure": ["Status.conditions[?type=='Failed'].status"]
                    }
                }
                observer_schema[resource] = default_schema
        return observer_schema
    except AttributeError:
        raise ValueError("Invalid application object or missing required fields")
    except Exception as e:
        raise RuntimeError(f"An error occurred while generating observer schema: {e}")

def formatmany(
		self,
		sql: AnyStr,
		many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
		out_style_sql = sql
		converted_params = []

		try:
			for params in many_params:
				if isinstance(params, Mapping):
					# Assuming named parameter style
					out_style_sql = re.sub(r':([a-zA-Z_]\w*)', r'%(\1)s', out_style_sql)
					converted_params.append(params)
				elif isinstance(params, Sequence):
					# Assuming ordinal parameter style
					out_style_sql = re.sub(r'\?', r'%s', out_style_sql)
					converted_params.append(list(params))
				else:
					raise ValueError("Invalid parameter type")
		except Exception as e:
			raise ValueError(f"Error in formatting SQL: {e}")

