def check_digests_present_and_used(self, manifest_files, digests_used):
    try:
        # Ensure manifest_files is a list of dictionaries, each containing a 'digest' key
        if not isinstance(manifest_files, list):
            raise ValueError("manifest_files must be a list.")

        manifest_digests = set()
        for entry in manifest_files:
            if not isinstance(entry, dict) or 'digest' not in entry:
                raise ValueError("Each entry in manifest_files must be a dictionary with a 'digest' key.")
            manifest_digests.add(entry['digest'])

        # Ensure digests_used is a set
        if not isinstance(digests_used, set):
            raise ValueError("digests_used must be a set.")

        # Check if all digests in digests_used are present in manifest_digests
        missing_digests = digests_used - manifest_digests
        if missing_digests:
            raise ValueError(f"The following digests are used but not present in the manifest: {missing_digests}")

        # Check if all digests in manifest_digests are used
        unused_digests = manifest_digests - digests_used
        if unused_digests:
            raise ValueError(f"The following digests are present in the manifest but not used: {unused_digests}")

        return True

    except Exception as e:
        print(f"An error occurred: {e}")
        return False

def validate_as_prior_version(self, prior):
    if not isinstance(prior, InventoryValidator):
        raise ValueError("The 'prior' parameter must be an instance of InventoryValidator.")

    # Assuming that the InventoryValidator class has an attribute `version`
    # and other necessary attributes to compare with the current instance.
    if prior.version >= self.version:
        raise ValueError("The 'prior' inventory version must be less than the current version.")

    # Add more validation logic as per the requirements, for example:
    # Check if all items in the prior inventory are present in the current inventory
    # with the same or newer versions or quantities.
    # This is a placeholder for such checks.
    for item_id, prior_item in prior.items.items():
        if item_id not in self.items:
            raise ValueError(f"Item {item_id} from the prior inventory is missing in the current inventory.")
        if prior_item['version'] > self.items[item_id]['version']:
            raise ValueError(f"Item {item_id} version in the prior inventory is newer than in the current inventory.")
        if prior_item['quantity'] > self.items[item_id]['quantity']:
            raise ValueError(f"Item {item_id} quantity in the prior inventory is greater than in the current inventory.")

    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    try:
        if version not in inventory:
            raise ValueError(f"Version {version} not found in inventory.")

        path_map = {}
        for entry in inventory[version]:
            logical_path = entry.get('logical_path')
            content_file = entry.get('content_file')

            if logical_path is None or content_file is None:
                raise ValueError("Each entry must contain 'logical_path' and 'content_file'.")

            if logical_path not in path_map:
                path_map[logical_path] = set()
            path_map[logical_path].add(content_file)

        return path_map

    except Exception as e:
        print(f"An error occurred: {e}")
        return {}

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity must be a dictionary")

    if not isinstance(manifest_files, list):
        raise ValueError("Manifest files must be a list")

    if 'files' not in fixity:
        raise KeyError("Fixity block must contain a 'files' key")

    if not isinstance(fixity['files'], list):
        raise ValueError("Files in fixity block must be a list")

    for file_entry in fixity['files']:
        if not isinstance(file_entry, dict):
            raise ValueError("Each file entry in fixity block must be a dictionary")

        if 'path' not in file_entry:
            raise KeyError("Each file entry must contain a 'path' key")

        if file_entry['path'] not in manifest_files:
            raise ValueError(f"File {file_entry['path']} in fixity block is not referenced in the manifest")

