def validate_version_inventories(self, version_dirs):
    if not isinstance(version_dirs, list) or not all(isinstance(d, str) for d in version_dirs):
        raise ValueError("version_dirs must be a list of strings")

    root_inventory = {}
    try:
        with open(f"{version_dirs[0]}/inventory.txt", 'r') as file:
            for line in file:
                content_path, digest = line.strip().split()
                root_inventory[content_path] = digest
    except FileNotFoundError:
        raise FileNotFoundError(f"Inventory file not found for version {version_dirs[0]}")
    except Exception as e:
        raise Exception(f"Error reading inventory for version {version_dirs[0]}: {e}")

    differing_digests = {}

    for version in version_dirs[1:]:
        version_inventory = {}
        try:
            with open(f"{version}/inventory.txt", 'r') as file:
                for line in file:
                    content_path, digest = line.strip().split()
                    version_inventory[content_path] = digest

            for content_path, digest in version_inventory.items():
                if content_path in root_inventory and root_inventory[content_path] != digest:
                    if content_path not in differing_digests:
                        differing_digests[content_path] = set()
                    differing_digests[content_path].add(digest)

        except FileNotFoundError:
            raise FileNotFoundError(f"Inventory file not found for version {version}")
        except Exception as e:
            raise Exception(f"Error reading inventory for version {version}: {e}")

    return differing_digests

def find_path_type(path):
    try:
        import os

        if not os.path.exists(path):
            return "path does not exist"

        if not os.path.isdir(path):
            return "path is not a directory"

        namaste_file = os.path.join(path, "0=ocfl_1.0")
        if os.path.isfile(namaste_file):
            return "root"

        namaste_file = os.path.join(path, "0=ocfl_object_1.0")
        if os.path.isfile(namaste_file):
            return "object"

        if any(os.path.isfile(os.path.join(path, f)) for f in os.listdir(path) if f.endswith(('.json', '.md5', '.sha256', '.sha512'))):
            return "file"

        return "unknown directory type"

    except Exception as e:
        return f"error: {str(e)}"

