def deep_merge_nodes(nodes):
    from collections import defaultdict

    def merge_values(key, value, merged):
        if key in merged:
            existing_value = merged[key]
            if isinstance(existing_value, list) and isinstance(value, list):
                # Both are MappingNodes, merge their contents
                existing_dict = dict(existing_value)
                new_dict = dict(value)
                merged[key] = list({**existing_dict, **new_dict}.items())
            else:
                # Last value wins for non-MappingNodes
                merged[key] = value
        else:
            merged[key] = value

    merged_dict = defaultdict(list)
    for key_node, value_node in nodes:
        try:
            key = key_node.value
            value = value_node.value if hasattr(value_node, 'value') else value_node
            if isinstance(value, list):
                # Assume MappingNode, convert to dict for merging
                value = dict(value)
            merge_values(key, value, merged_dict)
        except AttributeError as e:
            # Handle unexpected node structure
            raise ValueError(f"Node structure error: {e}")

    # Convert merged_dict back to list of tuples
    result = [(ScalarNode(tag=key_node.tag, value=key), MappingNode(tag=value_node.tag, value=value))
              if isinstance(value, list) else
              (ScalarNode(tag=key_node.tag, value=key), value)
              for key, value in merged_dict.items()]

    return result

