def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_results = {}
    remaining_arguments = list(unparsed_arguments)

    for subparser_name, parser in subparsers.items():
        try:
            parsed_args, remaining = parser.parse_known_args(remaining_arguments)
            parsed_results[subparser_name] = parsed_args
            remaining_arguments = remaining
        except SystemExit:
            # Ignore the exception raised by ArgumentParser when it encounters -h or --help
            continue
        except Exception as e:
            # Handle any other exceptions that might occur during parsing
            print(f"Error parsing arguments for subparser '{subparser_name}': {e}")
            continue

    return parsed_results, remaining_arguments

def deep_merge_nodes(nodes):
    from collections import defaultdict

    def merge_values(key, value, result):
        if key not in result:
            result[key] = value
        elif isinstance(value, MappingNode) and isinstance(result[key], MappingNode):
            merged_value = defaultdict(list)
            for k, v in result[key].value + value.value:
                merge_values(k, v, merged_value)
            result[key].value = list(merged_value.items())
        else:
            result[key] = value

    result = defaultdict(list)
    merged_nodes = {}

    for key, value in nodes:
        merge_values(key, value, merged_nodes)

    return list(merged_nodes.items())

