        return result
    except SystemExit:
        # Catch the exception raised by ArgumentParser for incorrect arguments
        return {}

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_results = {}
    remaining_arguments = unparsed_arguments.copy()

    for subparser_name, subparser in subparsers.items():
        try:
            parsed_namespace, unused_args = subparser.parse_known_args(remaining_arguments)
            parsed_results[subparser_name] = parsed_namespace
            remaining_arguments = unused_args
        except Exception as e:
            # Handle any exceptions that occur during parsing
            print(f"Failed to parse arguments for subparser '{subparser_name}': {e}")
            parsed_results[subparser_name] = None

    return parsed_results, remaining_arguments

