def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    try:
        if not isinstance(response, list):
            raise ValueError("Response must be a list.")
        if not isinstance(max_results, int) or max_results <= 0:
            raise ValueError("Max results must be a positive integer.")

        for i in range(0, len(response), max_results):
            yield response[i:i + max_results]
    except Exception as e:
        raise RuntimeError(f"An error occurred during paging: {e}")

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    try:
        suffixes = {'': 1, 'K': 1000, 'M': 1000**2, 'G': 1000**3, 'T': 1000**4}
        size = size.upper()
        if size[-1] in suffixes:
            return int(size[:-1]) * suffixes[size[-1]]
        else:
            return int(size)
    except (ValueError, KeyError):
        raise ValueError("Invalid size format. Please provide a size with a valid suffix (K, M, G, T) or as a plain integer.")

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise ValueError("All elements in the iterable must be dictionaries.")
        for key, value in d.items():
            if not isinstance(value, (int, float)):
                raise ValueError("All values in the dictionaries must be numbers.")
            if key in result:
                result[key] += value
            else:
                result[key] = value
    return result

