def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    import sys

    if platform == 'this':
        platform = 1 if sys.platform != 'win32' else 0

    if platform == 1:  # POSIX
        pattern = r"""('[^']*'|"[^"]*"|[^\s']+|\S+)"""
    elif platform == 0:  # Windows/CMD
        pattern = r"""('[^']*'|"[^"]*"|[^"\s']+|"[^"]*"[^"\s]*|'[^']*'[^'\s]*)"""
    else:
        raise ValueError("Unsupported platform value")

    try:
        return re.findall(pattern, s)
    except TypeError:
        raise ValueError("Input must be a string")

def addignored(ignored):
    try:
        # Run the git command to list ignored files
        result = subprocess.run(['git', 'check-ignore', '-v', ignored], capture_output=True, text=True, check=True)

        # Split the output into lines and extract file names
        ignored_files = [line.split()[-1] for line in result.stdout.strip().split('\n') if line]

        # Sort the list of ignored files
        ignored_files.sort()

        # Join the sorted list into a single string separated by commas
        return ','.join(ignored_files)

    except subprocess.CalledProcessError:
        # Handle the case where the git command fails
        return "Error: Unable to retrieve ignored files."
    except Exception as e:
        # Handle any other exceptions
        return f"Error: {str(e)}"

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None

    try:
        value, unit = frequency.split()
        value = int(value)
        unit = unit.rstrip('s').lower()  # Remove optional 's' for plural forms and convert to lowercase

        if unit == 'week':
            return datetime.timedelta(weeks=value)
        elif unit == 'day':
            return datetime.timedelta(days=value)
        elif unit == 'hour':
            return datetime.timedelta(hours=value)
        elif unit == 'minute':
            return datetime.timedelta(minutes=value)
        elif unit == 'second':
            return datetime.timedelta(seconds=value)
        else:
            raise ValueError(f"Unknown time unit: {unit}")
    except (ValueError, AttributeError) as e:
        raise ValueError(f"Invalid frequency format: {frequency}") from e

def make_find_paths(find_paths):
