def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    try:
        if not isinstance(commands, (list, tuple)) or not all(isinstance(cmd, str) for cmd in commands):
            raise ValueError("Commands must be a list or tuple of strings.")
        if not isinstance(args, (list, tuple)) or not all(isinstance(arg, str) for arg in args):
            raise ValueError("Arguments must be a list or tuple of strings.")

        full_command = list(commands) + list(args)
        if verbose:
            print(f"Running command: {' '.join(full_command)}")

        stderr = subprocess.DEVNULL if hide_stderr else None
        result = subprocess.run(full_command, cwd=cwd, env=env, capture_output=True, text=True, stderr=stderr)

        if result.returncode != 0:
            if verbose or not hide_stderr:
                print(f"Command failed with return code {result.returncode}: {result.stderr}")
            result.check_returncode()

        return result.stdout
    except Exception as e:
        print(f"An error occurred: {e}")
        return None

