def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        mean = 0.2
        sigma = 0.1
        return np.exp(-0.5 * ((x - mean) / sigma) ** 2) / (sigma * np.sqrt(2 * np.pi))
    except Exception as e:
        print(f"An error occurred: {e}")
        return None

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import logging
    import os
    import json

    def parse_config(filename):
        try:
            with open(filename, 'r') as file:
                config = json.load(file)
                if resolve_env:
                    config = resolve_environment_variables(config)
                return config
        except Exception as e:
            logger = logging.getLogger(__name__)
            return logger.error(f"Error parsing {filename}: {str(e)}")

    def resolve_environment_variables(config):
        if isinstance(config, dict):
            return {key: resolve_environment_variables(value) for key, value in config.items()}
        elif isinstance(config, list):
            return [resolve_environment_variables(item) for item in config]
        elif isinstance(config, str) and config.startswith('$'):
            return os.getenv(config[1:], config)
        else:
            return config

    if overrides is None:
        overrides = {}

    configs = {}
    log_records = []

    for filename in config_filenames:
        if not isinstance(filename, str):
            log_records.append(logging.makeLogRecord({
                'levelno': logging.ERROR,
                'level': 'ERROR',
                'msg': f"Invalid filename: {filename}"
            }))
            continue

        parsed_config = parse_config(filename)
        if isinstance(parsed_config, logging.LogRecord):
            log_records.append(parsed_config)
        else:
            configs[filename] = parsed_config

    configs.update(overrides)
    return configs, log_records

def from_ticks(cls, ticks, tz=None):
    if not isinstance(ticks, int) or not (0 <= ticks < 86400000000000):
        raise ValueError("ticks is out of bounds (0 <= ticks < 86400000000000)")
    seconds, nanoseconds = divmod(ticks, 1000000000)
    minutes, seconds = divmod(seconds, 60)
    hours, minutes = divmod(minutes, 60)
    return cls(hours, minutes, seconds, nanoseconds, tz)

