def scale(self, other=None, recompute=False):
    if other is None:
        if not hasattr(self, '_scale') or self._scale is None or recompute:
            self._scale = self._compute_scale()
        return self._scale
    else:
        if not isinstance(other, float):
            raise TypeError("other must be a float")
        if self._scale is None or self._scale == 0:
            raise LenaValueError("Histograms with scale equal to zero can't be rescaled.")
        factor = other / self._scale
        for i in range(len(self._bins)):
            self._bins[i] *= factor
        self._scale = other

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_: bin_

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("get_coordinate must be one of 'left', 'right', or 'middle'.")

    if not isinstance(field_names, tuple):
        raise TypeError("field_names must be a tuple.")

    if scale is not None and not isinstance(scale, bool) and not isinstance(scale, str):
        raise TypeError("scale must be None, True, or a string.")

    if scale is True:
        graph_scale = hist.scale
    else:
        graph_scale = scale

    graph_data = []
    for bin_ in hist.bins:
        if get_coordinate == "left":
            x = bin_.left_edge
        elif get_coordinate == "right":
            x = bin_.right_edge
        elif get_coordinate == "middle":
            x = (bin_.left_edge + bin_.right_edge) / 2

        value = make_value(bin_)

        if not isinstance(value, (tuple, list)):
            value = (value,)

        if len(field_names) != len(value) + 1:
            raise ValueError("Number of field names must match the dimension of the result.")

        point = {field_names[0]: x}
        for field, val in zip(field_names[1:], value):
            point[field] = val

        graph_data.append(point)

    return {"scale": graph_scale, "data": graph_data}

def _verify(iface, candidate, tentative=False, vtype=None):
    from zope.interface.exceptions import Invalid
    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"Candidate does not provide the interface {iface}")

    for name in iface.names():
        if name in iface.names(all=True):
            if not hasattr(candidate, name):
                errors.append(f"Candidate does not have attribute or method '{name}'")
                continue

            attr = getattr(candidate, name)
            if callable(attr):
                required = iface.get(name)
                if required:
                    requiredSig = required.signature()
                    try:
                        from inspect import signature
                        candidateSig = signature(attr)
                        if candidateSig != requiredSig:
                            errors.append(f"Method '{name}' has incorrect signature. Expected: {requiredSig}, got: {candidateSig}")
                    except Exception as e:
                        errors.append(f"Error checking signature for method '{name}': {str(e)}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("Multiple errors found:\n" + "\n".join(errors))

    return True

def verifyObject(iface, candidate, tentative=False):
    from zope.interface.verify import verifyObject as zope_verifyObject
    from zope.interface.exceptions import Invalid
    from zope.interface import providedBy

    errors = []

    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(f"Candidate does not claim to provide the interface {iface}")
        except TypeError:
            errors.append(f"Invalid candidate type for interface {iface}")

    for name in iface.names():
        if name not in dir(candidate):
            errors.append(f"Candidate does not define attribute or method '{name}'")
        else:
            attr = getattr(candidate, name)
            if callable(attr) and name in iface._MethodComponents:
                iface_method = iface[name]
                try:
                    iface_method.getSignatureInfo()  # Trigger signature check
                    from inspect import signature
                    if signature(attr) != signature(iface_method):
                        errors.append(f"Method '{name}' has incorrect signature")
                except (TypeError, ValueError) as e:
                    errors.append(f"Method '{name}' signature verification failed: {e}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    try:
        if not hasattr(iface, '__abstractmethods__'):
            raise ValueError("The iface parameter must be an abstract base class.")

        if not isinstance(candidate, type):
            raise ValueError("The candidate parameter must be a class type.")

        if tentative:
            return all(hasattr(candidate, method) for method in iface.__abstractmethods__)
        else:
            return issubclass(candidate, iface)
    except Exception as e:
        raise RuntimeError(f"An error occurred during verification: {e}")

def determineMetaclass(bases, explicit_mc=None):
    if explicit_mc is not None:
        return explicit_mc
    elif bases:
        metaclasses = {type(base) for base in bases}
        if len(metaclasses) > 1:
            raise TypeError("Conflicting metaclasses in bases")
        return next(iter(metaclasses), type)
    else:
        return type

def pop(self, key, default=__marker):
    if key in self:
        value = self[key]
        del self[key]
        return value
    elif default is not __marker:
        return default
    else:
        raise KeyError(key)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        # Assuming self is a dictionary-like object with LRU order
        key = next(reversed(self))
        value = self[key]
        del self[key]
        return key, value
    except StopIteration:
        raise KeyError("popitem(): dictionary is empty")

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    try:
        import random
        if not self:
            raise KeyError("popitem(): dictionary is empty")
        key = random.choice(list(self.keys()))
        value = self.pop(key)
        return (key, value)
    except Exception as e:
        raise RuntimeError(f"An error occurred: {e}")

