def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree

    try:
        # Try parsing as JSON
        return json.loads(document)
    except json.JSONDecodeError:
        try:
            # Try parsing as XML/XRD
            root = ElementTree.fromstring(document)
            if root.tag != '{http://docs.oasis-open.org/ns/xri/xrd-1.0}XRD':
                raise ValueError("Invalid XRD document")

            # Convert XRD to a dictionary
            xrd_dict = {}
            for element in root:
                tag = element.tag.split('}')[-1]
                if tag not in xrd_dict:
                    xrd_dict[tag] = []
                xrd_dict[tag].append(element.attrib)

            # Flatten single-item lists
            for key, value in xrd_dict.items():
                if len(value) == 1:
                    xrd_dict[key] = value[0]

            return xrd_dict
        except ElementTree.ParseError:
            raise ValueError("Document is neither valid JSON nor XRD")
        except Exception as e:
            raise ValueError(f"Error parsing XRD: {e}")

    except Exception as e:
        raise ValueError(f"Error parsing JSON: {e}")

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import requests
    import xml.etree.ElementTree as ET

    if not isinstance(handle, str) or not handle:
        raise ValueError("Handle must be a non-empty string")

    webfinger_url = f"https://{handle.split('@')[1]}/.well-known/webfinger?resource=acct:{handle}"

    try:
        response = requests.get(webfinger_url)
        response.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to retrieve webfinger document: {e}")

    try:
        root = ET.fromstring(response.content)
    except ET.ParseError as e:
        raise ValueError(f"Failed to parse webfinger document: {e}")

    parsed_data = {
        "subject": root.find("{http://jxr.us/ns/xdmppkix}subject").text if root.find("{http://jxr.us/ns/xdmppkix}subject") is not None else None,
        "links": []
    }

    for link in root.findall("{http://jxr.us/ns/xdmppkix}link"):
        link_data = {
            "rel": link.get("rel"),
            "href": link.get("href"),
            "type": link.get("type")
        }
        parsed_data["links"].append(link_data)

    return parsed_data

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    try:
        if method.lower() == "post":
            response = requests.post(url, data=data, timeout=timeout, *args, **kwargs)
        elif method.lower() == "get":
            response = requests.get(url, params=data, timeout=timeout, *args, **kwargs)
        else:
            raise ValueError(f"Unsupported method: {method}")

        response.raise_for_status()
        return response.status_code, None
    except Exception as e:
        return None, e

