    from os.path import exists

    if yaml_file is None or not isinstance(yaml_file, str):
        raise ValueError("yaml_file must be a non-empty string representing a file path")

    if not exists(yaml_file):
        raise FileNotFoundError(f"The file {yaml_file} does not exist")

    try:
        with open(yaml_file, 'r', encoding='utf-8') as file:
            data = yaml.safe_load(file)
    except yaml.YAMLError as exc:
        raise ValueError(f"Error parsing YAML file {yaml_file}: {exc}")

    if not isinstance(data, dict):
        raise IRValidatorException("YAML file does not contain a dictionary as the top-level structure")

    required_fields = {'name', 'version', 'description'}  # Example required fields, adjust as necessary
    missing_fields = required_fields - set(data.keys())
    if missing_fields:
        raise IRValidatorException(f"Mandatory fields missing in YAML file: {', '.join(missing_fields)}")

    return data

