def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    try:
        if not path.startswith(root):
            raise ValueError(f"Path '{path}' does not start with root '{root}'")
        stripped_path = path[len(root):]
        # Remove leading slash if present after stripping root
        if stripped_path.startswith('/'):
            stripped_path = stripped_path[1:]
        return stripped_path
    except Exception as e:
        raise Exception(f"Failed to strip root '{root}' from path '{path}': {str(e)}")
